def _enforce_halt(self):
    """Attempt to enforce halt via signal if agent PID is known."""
    if self.agent_pid and self._is_pid_running(self.agent_pid):
        try:
            os.kill(self.agent_pid, signal.SIGUSR1)
            self._log_enforcement_action("signal_sent", self.agent_pid, "SIGUSR1")
        except ProcessLookupError:
            self._log_enforcement_action("signal_failed", self.agent_pid, "PID not found")
        except PermissionError:
            self._log_enforcement_action("signal_failed", self.agent_pid, "Permission denied")

def _is_pid_running(self, pid: int) -> bool:
    """Check if a process with the given PID is running."""
    try:
        os.kill(pid, 0)
    except OSError:
        return False
    return True

