import sys
import threading
from src.CORE.compliance_auditor import ComplianceAuditor

class AgentInterceptor:
    def __init__(self, auditor):
        self.auditor = auditor
        self.original_execute = sys.executable

    def intercept_execute(self, *args, **kwargs):
        if not self.auditor.compliance_gate():
            raise Exception('Agent halted by ECA')
        return self.original_execute(*args, **kwargs)

def install_interceptor(auditor):
    interceptor = AgentInterceptor(auditor)
    sys.executable = interceptor.intercept_execute
